type AuthHandler struct {
	cfg  config.Config
	ur   *repo.UserRepo
}

func NewAuthHandler(db *pgxpool.Pool, cfg config.Config) *AuthHandler {
	return &AuthHandler{cfg: cfg, ur: repo.NewUserRepo(db)}
}

// @Summary Login and obtain a JWT
// @Tags    auth
// @Accept  json
// @Param   payload body types.LoginRequest true "Login"
// @Success 200 {object} types.LoginResponse
// @Failure 401 {object} types.APIError
// @Router  /api/auth/login [post]
func (h *AuthHandler) Login(c *gin.Context) {
	var in types.LoginRequest
	if err := c.ShouldBindJSON(&in); err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
		return
	}
	// fetch user
	user, hash, err := h.ur.GetWithHashByUsername(c, in.Username)
	if err != nil || user == nil || (user.IsActive != nil && !*user.IsActive) {
		_ = h.ur.RecordLoginFailure(c, in.Username)
		c.JSON(http.StatusUnauthorized, gin.H{"error": "invalid credentials"})
		return
	}
	// IP filter (optional; skip if you want to do this at middleware time)
	ip := c.ClientIP()
	if !auth.IsIPAllowed(ip, user.AllowedIPs, user.DeniedIPs) {
		_ = h.ur.RecordLoginFailure(c, in.Username)
		c.JSON(http.StatusUnauthorized, gin.H{"error": "ip not allowed"})
		return
	}
	// verify password
	if bcrypt.CompareHashAndPassword([]byte(hash), []byte(in.Password)) != nil {
		_ = h.ur.RecordLoginFailure(c, in.Username)
		c.JSON(http.StatusUnauthorized, gin.H{"error": "invalid credentials"})
		return
	}
	// load effective permissions as codes
	perms, err := h.ur.ListEffectivePermissions(c, user.ID)
	if err != nil {
		log.WithError(err).Warn("list permissions")
	}

	codes := make([]string, 0, len(perms))
	for _, p := range perms {
		codes = append(codes, p.Code)
	}

	// sign JWT
	token, err := auth.Sign(h.cfg.JWTSecret, h.cfg.JWTIssuer, h.cfg.JWTExpiry, user.ID, user.Username, user.UserRole, codes)
	if err != nil {
		log.WithError(err).Error("jwt sign")
		c.JSON(http.StatusInternalServerError, gin.H{"error": "login failed"})
		return
	}
	_ = h.ur.RecordLoginSuccess(c, user.ID)
	c.JSON(http.StatusOK, types.LoginResponse{Token: token})
}

